function timed(fn) {
  return (...args) => {
    const t0 = Date.now();
    const result = fn(...args);
    console.log(fn.name, Date.now() - t0, 'ms');
    return result;
  };
}

const withTiming = (fn) => async (...args) => {
  const t = performance.now();
  try { return await fn(...args); }
  finally { console.log(`${fn.name} took ${Math.round(performance.now() - t)} ms`); }
};
